/**
 * پلاگین امضای release برای پروژهٔ بومی تولیدی Expo Prebuild.
 * مقادیر فقط از متغیر محیطی خوانده می‌شوند و هرگز داخل کد یا مخزن قرار نمی‌گیرند.
 * اگر متغیرها نباشند، build release با خطا متوقف می‌شود (تا APK debug جا release نشود).
 */
const { withAppBuildGradle, createRunOncePlugin } = require("expo/config-plugins");

const RELEASE_SIGNING_BLOCK = `
        // HESABYAR-SIGNING-START (auto-generated by with-signed-release plugin)
        def hesabyarIsReleaseBuild = gradle.startParameter.taskNames.any { it.toLowerCase().contains("release") }
        def hesabyarKsFile = System.getenv("HESABYAR_KS_FILE")
        def hesabyarKsPass = System.getenv("HESABYAR_KS_PASS")
        def hesabyarKsAlias = System.getenv("HESABYAR_KS_ALIAS")
        def hesabyarKsKeyPass = System.getenv("HESABYAR_KS_KEY_PASS")
        if (hesabyarIsReleaseBuild && !(hesabyarKsFile != null && new File(hesabyarKsFile).exists() && hesabyarKsPass != null && hesabyarKsKeyPass != null)) {
            throw new GradleException("Secrets امضا یافت نشد (HESABYAR_KS_FILE/PASS/ALIAS/KEY_PASS). release بدون کلید ممنوع است — docs/signing.md")
        }
        signingConfigs {
            release {
                if (hesabyarKsFile != null && new File(hesabyarKsFile).exists() && hesabyarKsPass != null) {
                    storeFile file(hesabyarKsFile)
                    storePassword hesabyarKsPass
                    keyAlias hesabyarKsAlias
                    keyPassword hesabyarKsKeyPass
                }
            }
        }
        // HESABYAR-SIGNING-END
`;

function applySigning(gradleContents) {
  // اگر قبلاً تزریق شده، عقب‌گرد پذیر باشد (idempotent)
  if (gradleContents.includes("HESABYAR-SIGNING-START")) {
    return gradleContents.replace(
      /\/\/ HESABYAR-SIGNING-START[\s\S]*?\/\/ HESABYAR-SIGNING-END/,
      RELEASE_SIGNING_BLOCK.trimEnd()
    );
  }
  // جایگزینی signingConfig release پیش‌فرض (debug) با امضای واقعی
  let out = gradleContents;
  // فقط signingConfig داخل بلوک buildTypes.release را جایگزین کن (نه بلوک debug)
  if (/release\s*\{[^}]*?signingConfig\s+signingConfigs\.debug/.test(out)) {
    out = out.replace(
      /(release\s*\{[^}]*?)signingConfig\s+signingConfigs\.debug/,
      "$1signingConfig signingConfigs.release"
    );
  }
  // درج بلوک (defها + signingConfigs) هم‌سطح buildTypes، پیش از آن
  if (/^(\s*)buildTypes\s*\{/m.test(out)) {
    out = out.replace(/^(\s*)buildTypes\s*\{/m, `$1${RELEASE_SIGNING_BLOCK.trimEnd()}\n\n$1buildTypes {`);
  } else {
    throw new Error("buildTypes در app/build.gradle یافت نشد — پلاگین امضا شکست خورد");
  }
  return out;
}

const withSignedRelease = (config) =>
  withAppBuildGradle(config, (mod) => {
    mod.modResults.contents = applySigning(mod.modResults.contents);
    return mod;
  });

module.exports = createRunOncePlugin(withSignedRelease, "with-signed-release", "1.0.0");
